import numpy as np

# main code
def computeRadianceMap(images, log_exposure_times, response_curve, weighting_function):
    img_shape = images[0].shape
    img_rad_map = np.zeros(img_shape, dtype=np.float64)
    num_images = len(images)
    for i in range(img_shape[0]):
        for j in range(img_shape[1]):
            g = np.array([response_curve[images[k][i, j]] for k in range(num_images)])
            w = np.array([weighting_function(images[k][i, j]) for k in range(num_images)])
            SumW = np.sum(w)
            if SumW > 0:
                img_rad_map[i, j] = np.sum(w * (g - log_exposure_times) / SumW)
            else:
                img_rad_map[i, j] = g[num_images // 2] - log_exposure_times[num_images // 2]
    return img_rad_map

import numpy as np

# main code
def same_log10_order_of_magnitude(x, delta=0.1):
    dmin = np.log10(np.min(x) * (1 - delta))
    dmax = np.log10(np.max(x) * (1 + delta))
    return np.floor(dmin) == np.floor(dmax)

import numpy as np


def padding(x, maxlen=50, pvalue=0):
    return x[:maxlen] if len(x) >= maxlen else x + [pvalue] * (maxlen - len(x))

# main code
def _doc2ids(label_one_hot, s2_label_dict, data_list, maxlen, s2_label, char2idx, ftype):
    doc2ids = {}

    for f, seqs in data_list.items():
        seq2ids = []

        if ftype in {1, 3}:
            if f == 'label':
                seq2ids = [int(seq.strip()) for seq in seqs]
                if label_one_hot:
                    a = np.array(seq2ids)
                    b = np.zeros((a.size, a.max() + 1))
                    b[np.arange(a.size), a] = 1
                    seq2ids = b
            else:
                for seq in seqs:
                    seq2id = [char2idx.get(c, 1) for c in seq]
                    seq2id = padding(seq2id, maxlen=maxlen)
                    seq2ids.append(np.array(seq2id))

        elif ftype == 2:
            if f == 's2' and s2_label:
                for seq in seqs:
                    seq2id = [s2_label_dict.get(seq.strip(), 1) for _ in seq]
                    seq2id = padding(seq2id, maxlen=maxlen)
                    seq2ids.append(np.array(seq2id))
            else:
                for seq in seqs:
                    seq2id = [char2idx.get(c, 1) for c in seq]
                    seq2id = padding(seq2id, maxlen=maxlen)
                    seq2ids.append(np.array(seq2id))

        doc2ids[f] = np.array(seq2ids)

    return doc2ids

