import numpy as np

# main code
def keras_pad_seqs(sequences, maxlen, dtype, padding, truncating, value):
    num_samples = len(sequences) if hasattr(sequences, '__len__') else 0
    lengths = [len(x) if hasattr(x, '__len__') else 0 for x in sequences]

    maxlen = np.max(lengths) if maxlen is None else maxlen
    sample_shape = tuple()
    for s in sequences:
        if len(s) > 0:
            sample_shape = np.asarray(s).shape[1:]
            break

    x = np.full((num_samples, maxlen) + sample_shape, value, dtype=dtype)
    for idx, s in enumerate(sequences):
        if not len(s):
            continue

        trunc = s[-maxlen:] if truncating == 'pre' else s[:maxlen]
        trunc = np.asarray(trunc, dtype=dtype)

        if padding == 'post':
            x[idx, :len(trunc)] = trunc
        else:
            x[idx, -len(trunc):] = trunc

    return x

import numpy as np

# main code
def get_cm(i, cm_coef, alpha, cl_ext, cd_ext, alpha_low_deg, alpha_high_deg, cm0):
    cm_new = cm0

    if alpha[i] < alpha_low_deg or alpha[i] > alpha_high_deg:
        if -165 < alpha[i] < 165:
            if abs(alpha[i]) < 0.01:
                cm_new = cm0
            elif alpha[i] > 0:
                x = cm_coef * np.tan(np.radians(alpha[i]) - np.pi / 2) + 0.25
                cm_new = cm0 - x * (cl_ext[i] * np.cos(np.radians(alpha[i])) + cd_ext[i] * np.sin(np.radians(alpha[i])))
            else:
                x = cm_coef * np.tan(-np.radians(alpha[i]) - np.pi / 2) + 0.25
                cm_new = -(cm0 - x * (
                            -cl_ext[i] * np.cos(-np.radians(alpha[i])) + cd_ext[i] * np.sin(-np.radians(alpha[i]))))
        else:
            cm_lookup = {
                165: -0.4, 170: -0.5, 175: -0.25, 180: 0,
                -165: 0.35, -170: 0.4, -175: 0.2, -180: 0
            }
            cm_new = cm_lookup.get(alpha[i], cm0)

    return cm_new

