import numpy as np

# main code
def fix_knn_query(indices, distances, ref_idx):
    (fixed_ind, fixed_dist) = (indices.copy()[:, 1:], distances.copy()[:, 1:])
    mis_idx = indices[:, 0].reshape(1, -1)[0] != ref_idx
    n_mis = mis_idx.sum()
    if n_mis > 0:
        for (n, i, j, k) in zip(np.where(mis_idx)[0], ref_idx[mis_idx], indices[mis_idx], distances[mis_idx]):
            p = np.where(j == i)[0]
            if len(p) > 0:
                p = p[0]
                j = np.array(list(j[:p]) + list(j[p + 1:]))
                k = np.array(list(k[:p]) + list(k[p + 1:]))
            else:
                j = j[:-1]
                k = k[:-1]
            fixed_ind[n] = j
            fixed_dist[n] = k
    return (fixed_ind, fixed_dist, n_mis)

import numpy as np
from scipy import signal

# main code
def idxsOfRelativeExtrema(x, maxima, allowEq, axis):
    if len(x) == 0:
        return np.empty(1)
    if len(x) == 1:
        return np.zeros(1)

    x = np.asarray(x)
    pad = -np.inf if maxima else np.inf

    func = (
        np.greater_equal if maxima and allowEq else
        np.greater if maxima else
        np.less_equal if allowEq else
        np.less
    )

    if len(x.shape) == 1:
        x = np.r_[x, pad]
        return signal.argrelextrema(x, func, mode='wrap')[0]

    if axis == 0:
        pad = np.full((1, x.shape[1]), pad)
        x = np.vstack((x, pad))
        return signal.argrelextrema(x, func, mode='wrap', axis=axis)

    if axis == 1:
        pad = np.full((x.shape[0], 1), pad)
        x = np.hstack((x, pad))
        return signal.argrelextrema(x, func, mode='wrap', axis=axis)

    return np.array([])

