import numpy as np

# main code
def match_comp(rlt, rlt_lasso_Ydc, rlt_lasso_Yrawc, rlt_a, rlt_lasso_Yda, rlt_lasso_Yrawa, th):
    def vcorrcoef2(X, y):
        Xm = np.reshape(np.mean(X, axis=1), (X.shape[0], 1))
        ym = np.mean(y, keepdims=True)

        y = np.reshape(y, (-1, 1))

        r_num = np.sum((X - Xm) * (y - ym), axis=1)
        r_den = np.sqrt(np.sum((X - Xm) ** 2, axis=1) * np.sum((y - ym) ** 2))
        r = r_num / r_den
        return r

    K = rlt.shape[1]
    order_Yd = np.zeros([K])
    order_Yraw = np.zeros([K])
    for ii in range(K):
        temp = vcorrcoef2(rlt_lasso_Ydc.T, rlt[:, ii])
        temp2 = vcorrcoef2(rlt_lasso_Yrawc.T, rlt[:, ii])
        pos = np.argsort(-temp)[:sum(temp > th)]
        pos2 = np.argsort(-temp2)[:sum(temp2 > th)]
        if len(pos) > 0:
            spa_temp = np.where(np.matmul(rlt_a[:, [ii]].T, rlt_lasso_Yda[:, pos]) > 0)[1]
            if len(spa_temp) > 0:
                order_Yd[ii] = int(pos[spa_temp[0]])
            else:
                order_Yd[ii] = np.nan
        else:
            order_Yd[ii] = np.nan
        if len(pos2) > 0:
            spa_temp2 = np.where(np.matmul(rlt_a[:, [ii]].T, rlt_lasso_Yrawa[:, pos2]) > 0)[1]
            if len(spa_temp2) > 0:
                order_Yraw[ii] = int(pos2[spa_temp2[0]])
            else:
                order_Yraw[ii] = np.nan
        else:
            order_Yraw[ii] = np.nan
    order_Yd = np.asarray(order_Yd, dtype=int)
    order_Yraw = np.asarray(order_Yraw, dtype=int)
    return (order_Yd, order_Yraw)

import numpy as np
import scipy

# main code
def make_mask(corr_img_all_r, corr, mask_a, num_plane, times, max_allow_neuron_size):
    s = np.ones([3, 3])
    unit_length = int(mask_a.shape[0] / num_plane)
    dims = corr_img_all_r.shape
    corr_img_all_r = corr_img_all_r.reshape(dims[0], int(dims[1] / num_plane), num_plane, -1, order='F')
    mask_a = mask_a.reshape(corr_img_all_r.shape, order='F')
    corr_ini = corr
    for ii in range(mask_a.shape[-1]):
        for kk in range(num_plane):
            jj = 0
            corr = corr_ini
            if mask_a[:, :, kk, ii].sum() > 0:
                while jj <= times:
                    (labeled_array, num_features) = scipy.ndimage.measurements.label(corr_img_all_r[:, :, kk, ii] > corr, structure=s)
                    (u, indices, counts) = np.unique(labeled_array * mask_a[:, :, kk, ii], return_inverse=True, return_counts=True)
                    if len(u) == 1:
                        labeled_array = np.zeros(labeled_array.shape)
                        if corr == 0 or corr == 1:
                            break
                        else:
                            corr = np.maximum(0, corr - 0.1)
                            jj = jj + 1
                    else:
                        if num_features > 1:
                            c = u[1:][np.argmax(counts[1:])]
                            labeled_array = labeled_array == c
                            del c
                        if labeled_array.sum() / unit_length < max_allow_neuron_size or corr == 1 or corr == 0:
                            break
                        else:
                            corr = np.minimum(1, corr + 0.1)
                            jj = jj + 1
                mask_a[:, :, kk, ii] = labeled_array
    mask_a = (mask_a * 1).reshape(unit_length * num_plane, -1, order='F')
    return mask_a

import numpy as np

# main code
def CircleSegments(middle, radius, num_points, a_min, a_max, edge_length):
    number_points = max(num_points, 5)
    if edge_length > 0:
        number_points = int(np.floor(abs(radius / edge_length * (a_max - a_min)))) + 1
        if number_points < 5:
            number_points = 5
    delta = (a_max - a_min) / number_points
    closed = False
    if abs(abs(a_max - a_min) - 2 * np.pi) < 0.1 * abs(delta):
        closed = True
    t = np.linspace(a_min, a_max, number_points, not closed)
    points = [(middle[0] + radius * np.cos(angle), middle[1] + radius * np.sin(angle)) for angle in t]
    vertices = [(j, j + 1) for j in range(0, len(points) - 1, 1)]
    if closed:
        vertices += [(len(points) - 1, 0)]
    return (points, vertices)

from numpy import ma
import numpy as np


def _mask_to_limits(a, limits, inclusive):
    lower_limit, upper_limit = limits
    lower_include, upper_include = inclusive
    am = ma.MaskedArray(a)

    if lower_limit is not None:
        am = ma.masked_less(am, lower_limit) if lower_include else ma.masked_less_equal(am, lower_limit)

    if upper_limit is not None:
        am = ma.masked_greater(am, upper_limit) if upper_include else ma.masked_greater_equal(am, upper_limit)

    return am

# main code
def tsem(a, limits, inclusive, axis, ddof):
    a = np.asarray(a).ravel()

    if limits is None:
        return a.std(ddof=ddof) / np.sqrt(a.size) if a.size > 0 else np.nan

    am = _mask_to_limits(a, limits, inclusive)

    if am.count() == 0:
        return np.nan

    sd = np.sqrt(np.ma.var(am, ddof=ddof, axis=axis))
    return sd / np.sqrt(am.count())

import numpy as np

# main code
def sp1(data, maxvalue, issuccessful):
    if not isinstance(data, (list, tuple, np.ndarray)):
        return (np.nan, np.nan, np.nan)

    if issuccessful is not None and not isinstance(issuccessful, (list, tuple, np.ndarray)):
        return (np.nan, np.nan, np.nan)

    if issuccessful is not None and len(issuccessful) != len(data):
        return (np.nan, np.nan, np.nan)

    if issuccessful is not None:
        issuccessful = [issuccessful[i] for i in range(len(issuccessful)) if not np.isnan(data[i])]

    dat = [d for d in data if not np.isnan(d)]
    N = len(dat)

    if N == 0:
        return (np.nan, np.nan, np.nan)

    if issuccessful is not None:
        dat = [dat[i] for i in range(len(dat)) if issuccessful[i]]
    else:
        dat = [d for d in dat if d < maxvalue]

    succ = float(len(dat)) / N

    return (np.inf, 0.0, 0) if succ == 0 else (np.mean(dat) / succ, succ, len(dat))

