# main code
def to_dataframe(ifp, interactions, count, dtype, drop_empty, index_col):
    dtype = dtype or (np.uint8 if count else bool)
    empty_value = dtype(0)

    residue_pairs = sorted(set(residue_tuple for frame_ifp in ifp.values() for residue_tuple in frame_ifp))
    data = {residue_tuple: [] for residue_tuple in residue_pairs}
    index = []

    for i, frame_ifp in ifp.items():
        index.append(i)
        for residue_tuple in residue_pairs:
            ifp_dict = frame_ifp.get(residue_tuple, {})
            if count:
                bitvector = np.array([len(ifp_dict.get(i, ())) for i in interactions], dtype=dtype)
            else:
                bitvector = np.array([i in ifp_dict for i in interactions], dtype=bool)
            data[residue_tuple].append(bitvector)

    index = pd.Series(index, name=index_col)
    if not data:
        return pd.DataFrame([], index=index)

    values = np.array([
        np.hstack([bitvector_list[frame] for bitvector_list in data.values()])
        for frame in range(len(index))
    ])

    columns = pd.MultiIndex.from_tuples(
        [(str(lig_res), str(prot_res), i) for (lig_res, prot_res) in residue_pairs for i in interactions],
        names=['ligand', 'protein', 'interaction']
    )

    df = pd.DataFrame(values, columns=columns, index=index).astype(dtype)

    if drop_empty:
        mask = (df != empty_value).any(axis=0)
        df = df.loc[:, mask]

    return df

