import numpy as np

# main code
def subsample_array(x, step, pad, mode):
    if np.any(np.greater_equal(step, x.shape)):
        return np.empty(0)

    sbsz, dvmd = np.divmod(x.shape, step)

    if pad and np.any(dvmd):
        sbsz += np.clip(dvmd, 0, 1)
        psz = np.subtract(np.multiply(sbsz, step), x.shape)
        pdt = [(0, p) for p in psz]
        x = np.pad(x, pdt, mode=mode)

    outsz = step + tuple(sbsz)
    outstrd = x.strides + tuple(np.multiply(step, x.strides))

    return np.lib.stride_tricks.as_strided(x, outsz, outstrd)

import numpy as np
import scipy.special as sp

# main code
def first_order_score(y, mean, scale, shape, skewness):
    m1 = np.sqrt(shape) * sp.gamma((shape - 1.0) / 2.0) / (np.sqrt(np.pi) * sp.gamma(shape / 2.0))
    mean = mean + (skewness - 1.0 / skewness) * scale * m1
    if y - mean >= 0:
        return (shape + 1) / shape * (y - mean) / (np.power(skewness * scale, 2) + np.power(y - mean, 2) / shape)
    else:
        return (shape + 1) / shape * (y - mean) / (np.power(scale, 2) + np.power(skewness * (y - mean), 2) / shape)

