import numpy as np

# main code
def logbins_numba(lo, hi, ratio, N, prepend_zero):
    lo = int(lo)
    hi = int(hi)

    if ratio != 0 and N == 0:
        N = np.log(hi / lo) / np.log(ratio)
    elif N == 0:
        N = 10

    N = max(1, int(N))

    data10 = 10 ** np.linspace(np.log10(lo), np.log10(hi), N)
    data10 = np.rint(data10).astype(np.int_)
    data10_int = np.sort(np.unique(data10))

    if len(data10_int) == 0:
        return np.array([0] if prepend_zero else [])

    if data10_int[0] != lo:
        data10_int = np.insert(data10_int, 0, lo)
    if data10_int[-1] != hi:
        data10_int = np.append(data10_int, hi)
    if prepend_zero:
        data10_int = np.concatenate(([0], data10_int))

    return data10_int

