import numpy as np
from itertools import combinations_with_replacement


def fast_power(x, y):
    return np.prod(x**y, axis=1)

# main code
def build_Theta(data, derivatives, derivatives_description, P, data_description):
    n, d = data.shape
    m, d2 = derivatives.shape

    if n != m or (data_description is not None and len(data_description) != d):
        return np.empty((0, 0)), []

    rhs_functions = {}
    powers = []
    for p in range(1, P + 1):
        for comb in combinations_with_replacement(range(d), p):
            power = np.bincount(comb, minlength=d)
            powers.append(tuple(power))

    for power in powers:
        rhs_functions[power] = [power]

    Theta = np.ones((n, 1 + d2 + len(powers) * d2), dtype=np.complex64)
    descr = ['']

    Theta[:, 1:1 + d2] = derivatives
    descr.extend(derivatives_description)

    idx = 1 + d2
    data_powers = np.array([fast_power(data, np.array(power)) for power in rhs_functions])
    for D in range(d2):
        Theta[:, idx:idx + len(powers)] = data_powers.T * derivatives[:, D][:, None]
        if data_description is None:
            descr.extend([str(power) + derivatives_description[D] for power in rhs_functions])
        else:
            for power in rhs_functions:
                function_description = ''.join(
                    f"{data_description[j]}^{power[j]}" if power[j] > 1 else data_description[j]
                    for j in range(d) if power[j] != 0
                )
                descr.append(function_description + derivatives_description[D])
        idx += len(powers)

    return Theta, descr

