import pandas as pd
import datetime

# main code
def split_train_test_vec(data, split):
    train = pd.DataFrame(columns=data.columns)
    test = pd.DataFrame(columns=data.columns)
    all_categories = data['Category_id'].unique().tolist()

    for category in all_categories:
        df = data[data['Category_id'] == category].copy()
        max_date = datetime.datetime.strptime(df.Date.max(), '%Y-%m-%d')
        min_date = datetime.datetime.strptime(df.Date.min(), '%Y-%m-%d')
        days_diff = (max_date - min_date).days
        cutoff_date = max_date - datetime.timedelta(days=int(days_diff * (1 - split)))

        df.loc[:, 'cutoff'] = df['Date'].apply(
            lambda x: 1 if datetime.datetime.strptime(x, '%Y-%m-%d') > cutoff_date else 0
        )

        if not df[df['cutoff'] == 0].empty:
            train = pd.concat([train, df[df['cutoff'] == 0].dropna(axis=1, how='all')], ignore_index=True)

        if not df[df['cutoff'] == 1].empty:
            test = pd.concat([test, df[df['cutoff'] == 1].dropna(axis=1, how='all')], ignore_index=True)

    train_fixed = pd.DataFrame(columns=train.columns)
    test_fixed = pd.DataFrame(columns=test.columns)
    mode_train = int(train['Category_id'].value_counts().mode().min())
    mode_test = int(test['Category_id'].value_counts().mode().min())

    for (i, data_set) in enumerate([train, test]):
        data_set_categories = data_set['Category_id'].unique().tolist()
        for category in data_set_categories:
            df = data_set[data_set['Category_id'] == category].copy()
            df.sort_values(by=['Date'], axis=0, ascending=[True], inplace=True)

            if i == 0:
                if df.shape[0] == mode_train:
                    train_fixed = pd.concat([train_fixed, df.dropna(axis=1, how='all')], ignore_index=True)
                elif df.shape[0] > mode_train:
                    train_fixed = pd.concat([train_fixed, df.tail(mode_train).dropna(axis=1, how='all')],
                                            ignore_index=True)
            elif i == 1:
                if df.shape[0] == mode_test:
                    test_fixed = pd.concat([test_fixed, df.dropna(axis=1, how='all')], ignore_index=True)
                elif df.shape[0] > mode_test:
                    if not df.head(mode_test).empty:
                        test_fixed = pd.concat([test_fixed, df.head(mode_test).dropna(axis=1, how='all')],
                                               ignore_index=True)

    return train_fixed, test_fixed

import pandas as pd

def _lag_df(df, lags):
    df_lagged = pd.DataFrame()
    if isinstance(lags, int):
        lags = range(1, lags + 1)
    else:
        lags = [int(lag) for lag in lags]
    for lag in lags:
        temp_df = df.shift(lag).copy(deep=True)
        temp_df.columns = [str(i) + '_diff_lag_' + str(lag) for i in temp_df.columns]
        df_lagged = df_lagged.join(temp_df, how='outer')
    return df_lagged

# main code
def _get_X_y_standard_specification(series, lags):
    series_diff = series.diff().dropna()
    X = _lag_df(series_diff.to_frame(), lags).dropna()
    X['y_lagged'] = series.shift(1).loc[X.index]
    y = series_diff.loc[X.index]
    return (X, y)

import pandas as pd

def is_series_like(obj):
    return isinstance(obj, (pd.Series, pd.DataFrame))

# main code
def describe_numeric_aggregate(stats, name=None, is_timedelta_col=False, is_datetime_col=False, unit='ns'):
    (count, mean, std, min, q, max) = stats

    if is_timedelta_col:
        mean = pd.to_timedelta(mean, unit=unit)
        std = pd.to_timedelta(std, unit=unit)
        min = pd.to_timedelta(min, unit=unit)
        max = pd.to_timedelta(max, unit=unit)
        q = q.apply(lambda x: pd.to_timedelta(x, unit=unit))

    if is_datetime_col:
        min = pd.to_datetime(min, unit=unit)
        max = pd.to_datetime(max, unit=unit)
        q = q.apply(lambda x: pd.to_datetime(x, unit=unit))

    if is_datetime_col:
        part1 = pd.Series([count, min], index=['count', 'min'])
    else:
        part1 = pd.Series([count, mean, std, min], index=['count', 'mean', 'std', 'min'])

    q.index = [f'{l * 100:g}%' for l in q.index.to_list()]

    if is_series_like(q) and not isinstance(q, pd.Series):
        q = q.to_frame()

    part3 = pd.Series([max], index=['max'])

    result = pd.concat([part1, q, part3], sort=False)

    if is_series_like(result):
        result.name = name
    return result

