import numpy as np
import pandas as pd

# main code
def reduce_mem_usage(df):
    start_mem_usg = df.memory_usage().sum() / 1024 ** 2
    NAlist = []

    for col in df.columns:
        if df[col].dtype != object:  # Ignore object (string) columns
            IsInt = False
            mx = df[col].max()
            mn = df[col].min()

            # Handle NaNs and infinities
            if not np.isfinite(df[col]).all():  # Check for NaN, inf, -inf
                NAlist.append(col)
                df[col] = df[col].replace([np.inf, -np.inf], np.nan)  # Replace infinities with NaN
                df[col].fillna(mn if np.isfinite(mn) else 0, inplace=True)  # Replace NaNs with the min or 0

            # Check integer type safely
            if pd.api.types.is_integer_dtype(df[col]):
                IsInt = True
            else:
                asint = df[col].round().astype(np.int64, errors='ignore')  # Ensure rounding before casting
                result = (df[col] - asint).sum()
                if abs(result) < 0.01:  # Allow a small floating-point error margin
                    IsInt = True

            # Convert to optimal type
            if IsInt:
                if mn >= 0:
                    if mx < 255:
                        df[col] = df[col].astype(np.uint8)
                    elif mx < 65535:
                        df[col] = df[col].astype(np.uint16)
                    elif mx < 4294967295:
                        df[col] = df[col].astype(np.uint32)
                    else:
                        df[col] = df[col].astype(np.uint64)
                elif mn >= np.iinfo(np.int8).min and mx <= np.iinfo(np.int8).max:
                    df[col] = df[col].astype(np.int8)
                elif mn >= np.iinfo(np.int16).min and mx <= np.iinfo(np.int16).max:
                    df[col] = df[col].astype(np.int16)
                elif mn >= np.iinfo(np.int32).min and mx <= np.iinfo(np.int32).max:
                    df[col] = df[col].astype(np.int32)
                else:
                    df[col] = df[col].astype(np.int64)
            else:
                df[col] = df[col].astype(np.float32)  # Safely cast to float32 instead of float64

    mem_usg = df.memory_usage().sum() / 1024 ** 2
    mem_usg_percentage = 100 * mem_usg / start_mem_usg

    return df, NAlist, mem_usg_percentage

