import numpy as np

def add_symbol(symbol_name, symbols):
    if symbol_name not in symbols:
        symbols.append(symbol_name)


def remove_symbol(symbols, data_q, data_d):
    if isinstance(symbols, str):
        symbols = symbols.split(',')

    # Iterate over a copy to avoid modifying the list during iteration
    for symbol in symbols.copy():
        if symbol not in symbols:  # This check is redundant
            continue

        if data_d is not None and not data_d.empty:
            if isinstance(data_d.columns, pd.MultiIndex):
                if symbol in data_d.columns.get_level_values(0):
                    data_d.drop(symbol, axis=1, level=0, inplace=True)
                    data_d.columns = data_d.columns.remove_unused_levels()
            else:
                if symbol in data_d.columns:
                    data_d.drop(symbol, axis=1, inplace=True)

        if data_q is not None and not data_q.empty:
            if isinstance(data_q.columns, pd.MultiIndex):
                if symbol in data_q.columns.get_level_values(0):
                    data_q.drop(symbol, axis=1, level=0, inplace=True)
                    data_q.columns = data_q.columns.remove_unused_levels()
            else:
                if symbol in data_q.columns:
                    data_q.drop(symbol, axis=1, inplace=True)

        symbols.remove(symbol)


