def append_df_symbol(df, symbol_name, overwrite, symbols, data_d):
    if symbol_name in symbols:
        if overwrite:
            remove_symbol([symbol_name], data_q=None, data_d=data_d)
        else:
            return data_d

    df = df.copy()

    # Ensure data_d is not empty and has a MultiIndex
    if not data_d.empty and isinstance(data_d.columns, pd.MultiIndex):
        exist_fields = data_d.columns.levels[1]
    else:
        exist_fields = df.columns  # Default to df's columns if data_d is empty or not MultiIndex

    # Ensure all existing fields are present in df
    if set(exist_fields) - set(df.columns):
        df2 = pd.DataFrame(index=df.index, columns=exist_fields, data=np.nan)
        df2.update(df)
