import numpy as np
from scipy import optimize

def remove_outliers(arr):
    (q1, q3) = np.percentile(arr, [25, 75])
    iqr = q3 - q1
    (lower_bound, upper_bound) = (q1 - 1.5 * iqr, q3 + 1.5 * iqr)
    return np.array([x if lower_bound <= x <= upper_bound else np.median(arr) for x in arr])

def normalize(arr):
    return (arr - np.min(arr)) / (np.max(arr) - np.min(arr) + 1e-08)

def preprocess_data(data):
    (density, flow, updates, densityrv, flowrv, densityav, flowav, clnum, avgclsize) = data
    (density, flow, updates) = map(remove_outliers, [density, flow, updates])
    (densityrv, flowrv) = map(remove_outliers, [densityrv, flowrv])
    (densityav, flowav) = map(remove_outliers, [densityav, flowav])
    (clnum, avgclsize) = map(remove_outliers, [clnum, avgclsize])
    (density, flow, updates) = map(normalize, [density, flow, updates])
    (densityrv, flowrv) = map(normalize, [densityrv, flowrv])
    (densityav, flowav) = map(normalize, [densityav, flowav])
    (clnum, avgclsize) = map(normalize, [clnum, avgclsize])
    return (density, flow, updates, densityrv, flowrv, densityav, flowav, clnum, avgclsize)

def piecewise_linear(x, x0, y0, k1, k2):
    return np.piecewise(x, [x < x0], [lambda x: k1 * x + y0 - k1 * x0, lambda x: k2 * x + y0 - k2 * x0])

def fit_curve(x, y, max_index):
    p0 = [np.median(x), max(y), 0.5, -0.5]
    y_weight = np.full(len(y), 1.0)
    y_weight[0], y_weight[-1] = 0.1, 0.1
    y_weight[max_index] = 0.5
    (p, e) = optimize.curve_fit(piecewise_linear, x, y, p0, sigma=y_weight, absolute_sigma=True, maxfev=5000)
    return (p, np.sqrt(np.diag(e)))

def analyze_fundamental_diagram(data):
    (density, flow, updates, densityrv, flowrv, densityav, flowav, clnum, avgclsize) = data
    (FD_arr, FD_RV_arr, FD_AV_arr, params) = ([], [], [], [])
    flow_max_index = flow.tolist().index(max(flow))
    flowrv_max_index = flowrv.tolist().index(max(flowrv))
    flowav_max_index = flowav.tolist().index(max(flowav))
    N = 3000
    xd = np.linspace(0, 1, N)
    xdrv = np.linspace(0, 1, N)
    xdav = np.linspace(0, 1, N)
    (p, _) = fit_curve(density, flow, flow_max_index)
    FD_arr.extend([xd, piecewise_linear(xd, *p)])
    (prv, _) = fit_curve(densityrv, flowrv, flowrv_max_index)
    FD_RV_arr.extend([xdrv, piecewise_linear(xdrv, *prv)])
    (pav, _) = fit_curve(densityav, flowav, flowav_max_index)
    FD_AV_arr.extend([xdav, piecewise_linear(xdav, *pav)])
    params.extend([p, prv, pav])
    return (FD_arr, FD_RV_arr, FD_AV_arr, params)

def compute_stability(params):
    def calculate_critical_points(params):
        (x0, y0, k1, k2) = params
        return (x0, y0, k1, k2)

    overall_critical = calculate_critical_points(params[0])
    rv_critical = calculate_critical_points(params[1])
    av_critical = calculate_critical_points(params[2])

    stability_scores = {
        'Overall Stability': abs(params[0][2] - params[0][3]) / max(params[0][2], params[0][3]),
        'RV Stability': abs(params[1][2] - params[1][3]) / max(params[1][2], params[1][3]),
        'AV Stability': abs(params[2][2] - params[2][3]) / max(params[2][2], params[2][3])
    }

    return {'Critical Points': [overall_critical, rv_critical, av_critical], 'Stability': stability_scores}

# main code
def reveal_the_truth(raw_data):
    processed_data = preprocess_data(raw_data)
    (FD_arr, FD_RV_arr, FD_AV_arr, params) = analyze_fundamental_diagram(processed_data)
    analysis_results = compute_stability(params)
    return (FD_arr, FD_RV_arr, FD_AV_arr, params, analysis_results)

from scipy.sparse import linalg as sp_linalg
import numpy as np

def create_mv(curr_alpha, X1, n_features, n_samples):

    def _mv(x):
        if n_features > n_samples:
            return X1.matvec(X1.rmatvec(x)) + curr_alpha * x
        else:
            return X1.rmatvec(X1.matvec(x)) + curr_alpha * x
    return _mv

# main code
def _solve_sparse_cg(X, y, alpha, max_iter, rtol):
    (n_samples, n_features) = X.shape
    X1 = sp_linalg.aslinearoperator(X)
    coefs = np.empty((y.shape[1], n_features))
    for i in range(y.shape[1]):
        y_column = y[:, i]
        mv = create_mv(alpha[i], X1, n_features, n_samples)
        if n_features > n_samples:
            C = sp_linalg.LinearOperator((n_samples, n_samples), matvec=mv, dtype=X.dtype)
            (coef, info) = sp_linalg.cg(C, y_column, rtol=rtol)
            coefs[i] = X1.rmatvec(coef)
        else:
            y_column = X1.rmatvec(y_column)
            C = sp_linalg.LinearOperator((n_features, n_features), matvec=mv, dtype=X.dtype)
            (coefs[i], info) = sp_linalg.cg(C, y_column, maxiter=max_iter, rtol=rtol)
    return coefs

