    return params

import numpy as np
import scipy.stats as sps


def check_shape_loc_scale(spsdotwhat, shape_loc_scale):
    if np.any(np.isnan(shape_loc_scale)) or np.any(np.isinf(shape_loc_scale)):
        return True
    if spsdotwhat == sps.norm:
        return shape_loc_scale[1] <= 0
    if spsdotwhat in [sps.weibull_min, sps.gamma, sps.rice]:
        return shape_loc_scale[0] <= 0 or shape_loc_scale[2] <= 0
    if spsdotwhat == sps.beta:
        return shape_loc_scale[0] <= 0 or shape_loc_scale[1] <= 0 or shape_loc_scale[0] > 1e10 or shape_loc_scale[
            1] > 1e10
    return True

# main code
def fit(spsdotwhat, x, fwords):
    if np.unique(x).size < 2:
        return None
    shape_loc_scale = spsdotwhat.fit(x, **fwords) if hasattr(spsdotwhat, 'fit') else (np.nan,)

    if check_shape_loc_scale(spsdotwhat, shape_loc_scale):
        if spsdotwhat == sps.gamma:
            x_mean = np.mean(x) - fwords.get('floc', 0)
            x_var = np.var(x)
            scale = x_var / x_mean if x_mean != 0 else np.nan
            shape = x_mean / scale if scale != 0 else np.nan
            shape_loc_scale = (shape, fwords.get('floc', 0), scale)
        elif spsdotwhat == sps.beta:
            y = (x - fwords.get('floc', 0)) / fwords.get('fscale', 1)
            y_mean = np.mean(y)
            y_var = np.var(y)
            p = (y_mean ** 2 * (1.0 - y_mean) / y_var - y_mean) if y_var != 0 else np.nan
            q = (p * (1.0 - y_mean) / y_mean) if y_mean != 0 else np.nan
            shape_loc_scale = (p, q, fwords.get('floc', 0), fwords.get('fscale', 1))
        else:
            return None

    if check_shape_loc_scale(spsdotwhat, shape_loc_scale):
        return None

    ks_stat = sps.kstest(x, spsdotwhat.name, args=shape_loc_scale)[0]
    if ks_stat > 0.5:
        return None

    return shape_loc_scale

