from scipy import signal
import numpy as np

def preprocess_signal(sg):
    if sg is None or not isinstance(sg, np.ndarray):
        return None
    sg = np.nan_to_num(sg)
    sg = (sg - np.min(sg)) / (np.max(sg) - np.min(sg))
    return sg


def postprocess_signal(sg):
    sg = np.clip(sg, -1, 1)
    sg *= 1000
    return sg

# main code
def signal_filter(sg, freq, fr, order, mode, remove_mean):
    sg = preprocess_signal(sg)
    if sg is None or freq is None or fr is None:
        return None

    if mode in ["bandpass", "bandstop"]:
        if isinstance(freq, (list, tuple)) and len(freq) == 2:
            low, high = sorted(freq)
            if low <= 0 or high >= fr:
                return None
            normFreq = [low / fr, high / fr]
        else:

            low = np.random.uniform(0.1, fr * 0.4)
            high = np.random.uniform(low * 1.2, fr * 0.9)
            normFreq = [low / fr, high / fr]
    else:
        if freq <= 0 or freq >= fr:
            return None
        normFreq = freq / fr

    b, a = signal.butter(order, normFreq, mode)

    step = 10000
    for i in range(0, sg.shape[0], step):
        temp_sig = sg[i:i + step]
        if remove_mean:
            temp_sig -= temp_sig.mean(axis=1)[:, None]
        sg[i:i + step] = np.single(
            signal.filtfilt(b, a, temp_sig, method='gust', padtype='odd', padlen=3 * (max(len(b), len(a)) - 1))
        )

    sg = postprocess_signal(sg)
    return sg

