import numpy as np
import torch

def butter_bandpass(lowcut, highcut, fs, order=5):
    nyq = 0.5 * fs
    low = lowcut / nyq
    high = highcut / nyq
    return butter(order, [low, high], analog=False, btype='band', output='sos')

def scaling(X, sigma=0.05):
    scaling_factor = np.random.normal(loc=1.0, scale=sigma, size=(1, X.shape[1]))
    noise = np.matmul(np.ones((X.shape[0], 1)), scaling_factor)
    return X * noise

def verflip(sig):
    return sig[::-1, :]

def shift(sig, interval=20):
    for col in range(sig.shape[1]):
        offset = np.random.uniform(-interval / 100, interval / 100)
        sig[:, col] += offset
    return sig

def butter_bandpass_filter(data, lowcut, highcut, fs, order=5):
    sos = butter_bandpass(lowcut, highcut, fs, order=order)
    filtered_sig = np.zeros_like(data)
    for i in range(data.shape[1]):
        filtered_sig[:, i] = sosfilt(sos, data[:, i])
    return filtered_sig

# main code
def transform(sig, operation_list):

    if 'scaling' in operation_list:
        sig = scaling(sig)
    if 'verflip' in operation_list:
        sig = verflip(sig)
    if 'shift' in operation_list:
        sig = shift(sig)
    if 'butter_bandpass_filter' in operation_list:
        sig = butter_bandpass_filter(sig, 0.05, 46, 256)
    sig = sig.T
    return torch.tensor(sig.copy(), dtype=torch.float)

