import numpy as np
from scipy.interpolate import interp1d
from scipy.optimize import minimize
from scipy.ndimage import shift


def highres(y, kind='cubic', res=100):
    x = np.arange(len(y))
    f = interp1d(x, y, kind=kind)
    xnew = np.linspace(0, len(y) - 1, len(y) * res)
    return xnew, f(xnew)


def equalize_array_size(a1, a2):
    dif = len(a1) - len(a2)
    if dif < 0:
        a2 = a2[-dif // 2: len(a2) + dif // 2]
    elif dif > 0:
        a1 = a1[dif // 2: len(a1) - dif // 2]
    return a1, a2, dif


def phase_align(ref, target, roi, res=100):
    r1, r2 = highres(ref[roi[0]:roi[1]], res=res)[1], highres(target[roi[0]:roi[1]], res=res)[1]
    r1, r2 = r1 - np.mean(r1), r2 - np.mean(r2)
    cc = np.correlate(r1, r2, mode='full') / len(r1)
    return np.argmax(cc) * (1.0 / res) * (-1 if np.argmax(cc) == 0 else 1)


def chisqr_align(ref, target, roi=None, order=1, init=1, bound=0.1):
    ref, target, dif = equalize_array_size(ref, target)
    roi = roi or [0, len(ref) - 1]
    ref /= np.mean(ref[roi[0]:roi[1]])

    def cost(x):
        shifted = shift(target, x, order=order if order is not None else 1)  # Default to 1 if None
        return np.sum((ref - shifted / np.mean(shifted[roi[0]:roi[1]])) ** 2)

    result = minimize(cost, init, method='L-BFGS-B', bounds=[(init - bound, init + bound)])
    return result.x[0] + dif // 2


# main code
def align_nch_dataset(X, start, length, method='peak'):
    ch_avg = [np.mean([np.array(xx.split(',')).astype(float) if isinstance(xx, str) else xx for xx in x], axis=0) for x
              in X]
    max_ix = ch_avg[0].argmax()
    shifts = [0]

    for sample in ch_avg[1:]:
        if method == 'phase':
            s = phase_align(ch_avg[0], sample, [len(sample) // 4, len(sample) * 3 // 4])
        elif method == 'chisq':
            s = chisqr_align(ch_avg[0], sample, [len(sample) // 2, len(sample) * 3 // 4])
        else:
            s = max_ix - sample.argmax()
        shifts.append(s)

    return np.array([
        np.array([
            (np.array(xx.split(',')).astype(float) if isinstance(xx, str) else xx)[:length]
            if start >= shifts[sidx] else [0] * length
            for xx in sample
        ]) for sidx, sample in enumerate(X)
    ]), shifts

