from sklearn.preprocessing import StandardScaler
from scipy.sparse import coo_matrix

def preprocess_data(X, y):
    X = coo_matrix(X)
    y = StandardScaler().fit_transform(y)
    return X, y

def create_mv(curr_alpha, X1, X):
    if X.shape[1] > X.shape[0]:
        def _mv(x):
            return X1.matvec(X1.rmatvec(x)) + curr_alpha * x
    else:
        def _mv(x):
            return X1.rmatvec(X1.matvec(x)) + curr_alpha * x
    return _mv

# main code
def _solve_sparse_cg(X, y, alpha, max_iter=None, tol=0.001, verbose=0):
    X, y = preprocess_data(X, y)
    n_samples, n_features = X.shape
    X1 = sp_linalg.aslinearoperator(X)
    coefs = np.empty((y.shape[1], n_features))

    for i in range(y.shape[1]):
        y_column = y[:, i]
        mv = create_mv(alpha[i], X1, X)

        if n_features > n_samples:
            C = sp_linalg.LinearOperator((n_samples, n_samples), matvec=mv, dtype=X.dtype)
            coef, info = sp_linalg.cg(C, y_column, rtol=tol)
            coefs[i] = X1.rmatvec(coef)
        else:
            y_column = X1.rmatvec(y_column)
            C = sp_linalg.LinearOperator((n_features, n_features), matvec=mv, dtype=X.dtype)
            coefs[i], info = sp_linalg.cg(C, y_column, maxiter=max_iter, rtol=tol)

        if max_iter is None and info > 0 and verbose:
            pass

    return coefs if coefs.size > 0 else None

import numpy as np
from numpy import ma


def _contains_nan(a, nan_policy, use_summation='propagate'):
    policies = ['propagate', 'omit']
    if nan_policy not in policies:
        nan_policy = 'propagate'

    try:
        if use_summation:
            contains_nan = np.isnan(np.sum(a))
        else:
            contains_nan = np.isnan(a).any()
    except TypeError:
        contains_nan = False
        nan_policy = 'omit'

    return (contains_nan, nan_policy)


def count(x):
    return np.count_nonzero(x, -1)


# main code
def percentileofscore(a, score, kind, nan_policy):
    a = np.asarray(a)
    n = len(a)
    score = np.asarray(score)
    (cna, npa) = _contains_nan(a, nan_policy, use_summation=False)
    (cns, nps) = _contains_nan(score, nan_policy, use_summation=False)

    if cna or cns:
        if nan_policy == 'omit':
            if cna:
                a = ma.masked_where(np.isnan(a), a)
                n = a.count()
            if cns:
                score = ma.masked_where(np.isnan(score), score)
        elif nan_policy == 'propagate':
            n = 0

    if n == 0:
        perct = np.full_like(score, np.nan, dtype=np.float64)
    else:
        score = score[..., None]

        if kind == 'rank':
            left = count(a < score)
            right = count(a <= score)
            plus1 = left < right
            perct = (left + right + plus1) * (50.0 / n)
        elif kind == 'strict':
            perct = count(a < score) * (100.0 / n)
        elif kind == 'weak':
            perct = count(a <= score) * (100.0 / n)
        elif kind == 'mean':
            left = count(a < score)
            right = count(a <= score)
            perct = (left + right) * (50.0 / n)
        else:
            perct = np.nan

    perct = ma.filled(perct, np.nan)
    if perct.ndim == 0:
        return perct[()]
    return perct

