def get_top_k_features(features, model, top_n_features):

    feature_importances = model.feature_importances_
    feature_imp_sorted = pd.DataFrame({'feature': features, 'importance': feature_importances})
    return feature_imp_sorted.nlargest(top_n_features, 'importance')['feature'].tolist()

