    model_params = {'Regression': {'objective': 'regression', 'metric': 'rmse'}, 'Binary_Classification': {'objective': 'binary', 'metric': 'auc'}, 'Multi_Classification': {'objective': 'multiclass', 'metric': 'multi_logloss'}}
    params = model_params[model_type]
    params.update({'boosting_type': 'gbdt', 'verbose': -1, 'seed': 42, 'feature_fraction': 0.7, 'bagging_fraction': 0.7, 'max_depth': 4, 'n_estimators': 50, 'num_leaves': 15, 'min_data_in_leaf': 20, 'subsample_freq': 1})
