from sklearn import metrics


def cal_fnr(fn, tp):
    return fn / (fn + tp)


def cal_fpr(fp, tn):
    return fp / (fp + tn)


def cal_tpr(tp, fn):
    return tp / (tp + fn)


def cal_tnr(tn, fp):
    return tn / (tn + fp)

# main code
def eval(df):
    tasks = ['gender', 'age', 'country', 'ethnicity']
    scores = {
        'accuracy': metrics.accuracy_score(y_true=df.label, y_pred=df.pred),
        'f1-macro': metrics.f1_score(y_true=df.label, y_pred=df.pred, average='macro'),
        'f1-weight': metrics.f1_score(y_true=df.label, y_pred=df.pred, average='weighted'),
        'auc': metrics.auc(*metrics.roc_curve(y_true=df.label, y_score=df.pred_prob)[:2])
    }

    for task in tasks:
        if task not in df.columns or df[task].isnull().all():
            continue

        scores[task] = {'fned': 0.0, 'fped': 0.0, 'tped': 0.0, 'tned': 0.0}
        task_df = df[df[task].notnull()]
        tn, fp, fn, tp = metrics.confusion_matrix(y_true=task_df.label, y_pred=task_df.pred).ravel()

        for group in task_df[task].unique():
            group_df = task_df[task_df[task] == group]
            g_tn, g_fp, g_fn, g_tp = metrics.confusion_matrix(y_true=group_df.label, y_pred=group_df.pred).ravel()

            scores[task]['fned'] += abs(cal_fnr(fn, tp) - cal_fnr(g_fn, g_tp))
            scores[task]['fped'] += abs(cal_fpr(fp, tn) - cal_fpr(g_fp, g_tn))
            scores[task]['tped'] += abs(cal_tpr(tp, fn) - cal_tpr(g_tp, g_fn))
            scores[task]['tned'] += abs(cal_tnr(tn, fp) - cal_tnr(g_tn, g_fp))

    return scores

