from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score, precision_recall_curve, confusion_matrix, auc, roc_curve
from scipy.special import expit


def bootstrap_ci(labels, logits, decision_threshold, nsamples):
    metrics = {'auc_roc': [], 'auc_pr': [], 'sens': [], 'spec': [], 'ppv': [], 'npv': []}

    for _ in tqdm(range(nsamples), leave=False):
        idx = np.random.randint(len(labels), size=len(labels))

        metrics['auc_roc'].append(roc_auc_score(labels[idx], logits[idx]))
        precision, recall, _ = precision_recall_curve(labels[idx], logits[idx])
        metrics['auc_pr'].append(auc(recall, precision))

        tn, fp, fn, tp = confusion_matrix(labels[idx], logits[idx] > decision_threshold).ravel()

        for key, value in zip(['sens', 'spec', 'ppv', 'npv'],
                              [tp / (tp + fn), tn / (tn + fp), tp / (tp + fp), tn / (fn + tn)]):
            metrics[key].append(value if np.isfinite(value) else 0)

    return {k: np.percentile(v, (2.5, 97.5)) for k, v in metrics.items()}

# main code
def calculate_subgroup_performance(subgroup_df, bootstrap=False, bootstrap_nsamples=2000, cm_threshold=0.045):
    def extract_labels_preds(label_cols, pred_cols):
        return np.append(*[subgroup_df[col] for col in label_cols]), np.append(*[subgroup_df[col] for col in pred_cols])

    labels_malignant, preds_malignant = extract_labels_preds(['labels_lm', 'labels_rm'], ['preds_lm', 'preds_rm'])
    labels_benign, preds_benign = extract_labels_preds(['labels_lb', 'labels_rb'], ['preds_lb', 'preds_rb'])

    if preds_malignant.min() < 0:
        preds_malignant, preds_benign = map(expit, [preds_malignant, preds_benign])

    metrics = {
        'AUROC malignant': round(roc_auc_score(labels_malignant, preds_malignant), 3),
        'AUROC benign': round(roc_auc_score(labels_benign, preds_benign), 3),
    }

    if bootstrap:
        metrics['cis'] = bootstrap_ci(labels_malignant, preds_malignant, cm_threshold, bootstrap_nsamples)

    malignant_fpr, malignant_tpr, malignant_thresholds = roc_curve(labels_malignant, preds_malignant)
    precision, recall, _ = precision_recall_curve(labels_malignant, preds_malignant)

    cm = confusion_matrix(labels_malignant, preds_malignant > cm_threshold)
    tn, fp, fn, tp = cm.ravel()

    for key, value in zip(['AUPRC', 'Sensitivity', 'Specificity', 'PPV', 'NPV'],
                          [auc(recall, precision), tp / (tp + fn), tn / (tn + fp), tp / (tp + fp), tn / (fn + tn)]):
        metrics[key] = round(value if np.isfinite(value) else 0, 3)

    return {**metrics, 'malignant_fpr': malignant_fpr, 'malignant_tpr': malignant_tpr,
            'malignant_thresholds': malignant_thresholds, 'precision': precision, 'recall': recall}

import numpy as np
from sklearn.metrics import balanced_accuracy_score

# main code
def compute_balanced_accuracy(target, y_test, y_preds):
    bal_scores = []

    if isinstance(target, str) or (hasattr(target, '__len__') and len(target) <= 1):
        bal_score = balanced_accuracy_score(y_test, y_preds)
        bal_scores.append(bal_score)
    else:
        for each_i, target_name in enumerate(target):
            bal_score = balanced_accuracy_score(y_test.iloc[:, each_i], y_preds[:, each_i])
            bal_scores.append(bal_score)

    return np.mean(bal_scores) if bal_scores else 0.0

from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import roc_curve, auc
from sklearn import svm
from sklearn.neighbors import KNeighborsClassifier
import pandas as pd
import numpy as np


# main code
def machine_classification(X_train, y_train, X_test, y_test):
    scores = []

    if y_train.ndim == 3:
        y_train = y_train[:, 0, :]
        y_test = y_test[:, 0, :]

    if y_test.shape[-1] == 1:
        classifiers = {
            "GCN+rf": RandomForestClassifier(),
            "GCN+svm": svm.SVC(C=1, kernel='rbf', gamma='auto', probability=True),
            "GCN+knn": KNeighborsClassifier(n_neighbors=5)
        }

        for model_type, clf in classifiers.items():
            clf.fit(X_train, y_train.ravel())  # Flatten target labels if necessary
            y_score = clf.predict_proba(X_test)[:, 1] if hasattr(clf, "predict_proba") else clf.decision_function(X_test)
            fpr, tpr, _ = roc_curve(y_test.ravel(), y_score)
            scores.append([model_type, auc(fpr, tpr)])

    else:
        auc_results = {"GCN+rf": [], "GCN+svm": [], "GCN+knn": []}

        classifiers = {
            "GCN+rf": RandomForestClassifier(),
            "GCN+svm": svm.SVC(C=1, kernel='rbf', gamma='auto', probability=True),
            "GCN+knn": KNeighborsClassifier(n_neighbors=5)
        }

        for i in range(y_test.shape[1]):
            if np.max(y_train[:, i]) == 0 or np.max(y_test[:, i]) == 0:
                continue

            for model_type, clf in classifiers.items():
                clf.fit(X_train, y_train[:, i])

                if hasattr(clf, "predict_proba"):
                    y_score = clf.predict_proba(X_test)[:, 1]
                else:
                    y_score = clf.decision_function(X_test)

                fpr, tpr, _ = roc_curve(y_test[:, i], y_score)
                auc_score = auc(fpr, tpr)

                if auc_score > 0:
                    auc_results[model_type].append(auc_score)

        for model_type, auc_list in auc_results.items():
            scores.append([model_type, np.mean(auc_list) if auc_list else 0])

    return pd.DataFrame(scores, columns=["Model", "AUC"])

