import tensorflow as tf

def norm2_grad(u, x):
    with tf.GradientTape() as tape:
        tape.watch(x)
        grad = tape.gradient(u, x)
    return tf.reduce_sum(grad ** 2, axis=1) if grad is not None else tf.zeros_like(x[:, 0])


# main code
def h2(u, x, dimension):
    with tf.GradientTape(persistent=True) as tape:
        tape.watch(x)
        ans = tf.reduce_mean(u ** 2 + norm2_grad(u, x))
        grad = tape.gradient(u, x)

    if grad is not None:
        for i in range(dimension):
            g = tape.gradient(grad[:, i], x)
            ans += tf.reduce_mean(tf.reduce_sum(g ** 2, axis=1)) if g is not None else 0.0

    return tf.sqrt(ans) if ans is not None else tf.constant(0.0)

import tensorflow as tf

def apply_box_deltas(boxes, deltas):
    height, width = boxes[:, 2] - boxes[:, 0], boxes[:, 3] - boxes[:, 1]
    center_y, center_x = boxes[:, 0] + 0.5 * height, boxes[:, 1] + 0.5 * width
    center_y += deltas[:, 0] * height
    center_x += deltas[:, 1] * width
    height, width = height * tf.exp(deltas[:, 2]), width * tf.exp(deltas[:, 3])
    return tf.stack([center_y - 0.5 * height, center_x - 0.5 * width, center_y + 0.5 * height, center_x + 0.5 * width], axis=1)

def clip_boxes(boxes, window):
    wy1, wx1, wy2, wx2 = tf.split(window, 4)
    y1, x1, y2, x2 = tf.split(boxes, 4, axis=1)
    return tf.concat([tf.clip_by_value(y1, wy1, wy2), tf.clip_by_value(x1, wx1, wx2), tf.clip_by_value(y2, wy1, wy2), tf.clip_by_value(x2, wx1, wx2)], axis=1)

def trim_zeros(boxes):
    mask = tf.reduce_sum(tf.abs(boxes), axis=1) > 0
    return tf.boolean_mask(boxes, mask), mask

def denorm_boxes(boxes, shape):
    scale = tf.cast([shape[0] - 1, shape[1] - 1, shape[0] - 1, shape[1] - 1], tf.float32)
    return tf.cast(tf.round(boxes * scale + [0, 0, 1, 1]), tf.int32)


# main code
def refine_detections(rois, probs, deltas, window, bbox_std_dev):
    class_ids = tf.argmax(probs, axis=1, output_type=tf.int32)
    indices = tf.stack([tf.range(tf.shape(probs)[0]), class_ids], axis=1)
    class_scores, deltas_specific = tf.gather_nd(probs, indices), tf.gather_nd(deltas, indices)
    refined_rois = clip_boxes(apply_box_deltas(rois, deltas_specific * bbox_std_dev), window)
    keep = tf.where(class_ids > 0)[:, 0]
    detected_regions, _ = trim_zeros(tf.gather(refined_rois, keep))
    return tf.shape(denorm_boxes(detected_regions, [256, 256]))[0], tf.cast(denorm_boxes(detected_regions, [256, 256]), tf.float32)

