import numpy as np
import tensorflow as tf


def calculate_state(probability):
    return np.random.binomial(1, probability).astype(np.float64)

# main code
def parallel_sample(inpt, n_step_MC, p_0, p_1, n_chains, save_evolution,
                    hidden_biases, visible_biases, weights, _v_dim):
    if inpt is None or inpt.size == 0:
        inpt = np.random.choice([0, 1], size=(n_chains, _v_dim), p=[p_0, p_1]).astype(np.float64)
    elif inpt.ndim != 2:
        inpt = inpt.reshape(1, -1)

    if save_evolution:
        evolution = np.empty((n_step_MC, inpt.shape[0], _v_dim))
        evolution[0] = inpt

    hidden_probabilities = tf.sigmoid(tf.tensordot(inpt, weights, axes=[[1], [1]]) + hidden_biases)
    hidden_states = calculate_state(hidden_probabilities)

    for i in range(n_step_MC):
        visible_probabilities = tf.sigmoid(tf.tensordot(hidden_states, weights, axes=[[1], [0]]) + visible_biases)
        visible_states = calculate_state(visible_probabilities)
        hidden_probabilities = tf.sigmoid(tf.tensordot(visible_states, weights, axes=[[1], [1]]) + hidden_biases)
        hidden_states = calculate_state(hidden_probabilities)

        if save_evolution:
            evolution[i] = visible_states

    if save_evolution:
        return visible_states, visible_probabilities, inpt, evolution
    return visible_states, visible_probabilities, inpt

