import tensorflow as tf


def _num_labels(weights):
    return tf.where(tf.equal(tf.reduce_sum(weights), 0.0), 1.0, tf.reduce_sum(weights))

# main code
def classification_loss(logits, labels, weights):
    inner_dim = tf.shape(logits)[-1]

    if tf.equal(inner_dim, 1):
        loss = tf.nn.sigmoid_cross_entropy_with_logits(
            logits=tf.reshape(logits, tf.shape(labels)),
            labels=tf.cast(labels, tf.float32),
        )
    else:
        loss = tf.nn.sparse_softmax_cross_entropy_with_logits(
            logits=logits, labels=labels
        )

    return tf.reduce_sum(weights * loss) / _num_labels(weights)

