import torch

# main code
def matrix_mul(input, weight, bias):
    feature_list = []
    for feature in input:
        feature = torch.mm(feature, weight)
        if bias is not None:
            feature = feature + bias.expand(feature.size(0), bias.size(1))
        feature = torch.tanh(feature)
        feature_list.append(feature)
    max_columns = max((f.size(1) for f in feature_list))
    padded_features = [torch.nn.functional.pad(f, (0, max_columns - f.size(1))) for f in feature_list]
    return torch.cat(padded_features, dim=0).squeeze()

