import torch

def get_feature_combo_data(data, arg):
    if 'ntu' in arg.train_feeder_args['data_path']:
        datatype = 'ntu'
    elif 'kinetics' in arg.train_feeder_args['data_path']:
        datatype = 'kinetics'
    else:
        return data

    if datatype == 'ntu':
        if arg.feature_combo == 'angular':
            data = data[:, 6:, :, :, :]
        elif arg.feature_combo == 'joint':
            data = data[:, :3, :, :, :]
        elif arg.feature_combo == 'bone':
            data = data[:, 3:6, :, :, :]
        elif arg.feature_combo == 'joint+angular':
            data = torch.cat((data[:, :3, :, :, :], data[:, 6:, :, :, :]), dim=1)
        elif arg.feature_combo == 'bone+angular':
            data = torch.cat((data[:, 3:6, :, :, :], data[:, 6:, :, :, :]), dim=1)
        elif arg.feature_combo == 'no_head':
            data = data[:, :15, :, :, :]
        elif arg.feature_combo == 'joint+bone':
            data = data[:, :6, :, :, :]
        elif arg.feature_combo == 'local_bone_angle':
            data = torch.cat((data[:, :6, :, :, :], data[:, 6:7, :, :, :]), dim=1)
        elif arg.feature_combo == 'central_angle':
            data = torch.cat((data[:, :6, :, :, :], data[:, 7:9, :, :, :]), dim=1)

    elif datatype == 'kinetics':
        if arg.feature_combo == 'joint':
            data = torch.cat((data[:, :2, :, :, :], data[:, -1:, :, :, :]), dim=1)
        elif arg.feature_combo == 'bone':
            data = torch.cat((data[:, 2:4, :, :, :], data[:, -1:, :, :, :]), dim=1)
        elif arg.feature_combo == 'joint+angle':
            data = torch.cat((data[:, :2, :, :, :], data[:, 4:, :, :, :]), dim=1)
        elif arg.feature_combo == 'bone+angle':
            data = torch.cat((data[:, 2:4, :, :, :], data[:, 4:, :, :, :]), dim=1)

    return data

# main code
def get_model_features(loader_name, model, arg, data_loader):
    rtn_labels = []

    with torch.no_grad():
        model.to_fc_last = False
        model = model.to(torch.device("cpu"))
        model.eval()
        output_list = []

        for ln in loader_name:
            for batch_idx, (data, label, index) in enumerate(data_loader[ln]):
                rtn_labels.append(label)
                data = data.float().to(torch.device("cpu"))
                data = get_feature_combo_data(data, arg)

                if arg.to_add_onehot:
                    one_hot = torch.eye(arg.model_args['num_point']).unsqueeze(1).unsqueeze(-1).unsqueeze(0)
                    one_hot = one_hot.repeat(data.shape[0], 1, data.shape[2], 1, arg.model_args['num_person'])
                    data = torch.cat((data, one_hot), dim=1)

                output = model(data, set_to_fc_last=False)
                output_list.append(output.cpu())

    output_list = torch.cat(output_list, dim=0)
    rtn_labels = torch.cat(rtn_labels, dim=0)

    return output_list, rtn_labels

