import numpy as np
import torch.nn.functional as F


def concat_pos(x):
    L = x.shape[-2]
    if L <= 1:
        return x

    pos = (2 * np.pi * torch.arange(L) / L).view(-1, 1)
    cos = torch.zeros_like(x[..., :1]) + pos.cos()
    sin = torch.zeros_like(x[..., :1]) + pos.sin()
    return torch.cat((x, cos, sin), dim=-1)

# main code
def atomic(L=None, task=None, batch_shape=()):
    if L is None or L <= 1:
        return None
    seq = torch.randn(size=batch_shape + (L,))
    F.normalize(seq, p=np.inf, dim=-1, out=seq)
    x = seq.clone()

    if task == 'cumsum':
        y = seq.cumsum(-1) / torch.sqrt(torch.arange(1, L + 1, dtype=torch.float32))
    elif task == 'cummax':
        y = seq.cummax(-1).values
    elif task == 'reverse':
        x = F.pad(seq, (0, L))
        y = seq.flip(-1)
    elif task == 'sort':
        x = F.pad(seq, (0, L))
        sorted_indices = (seq - seq[..., :1]).abs().sort(dim=-1, stable=True)[1]
        y = seq.gather(-1, sorted_indices)
    else:
        return None
    x = concat_pos(x.unsqueeze(-1))
    y = y.unsqueeze(-1)

    return (x, y)

