def batched_grid_apply(img, grid, batch_size=32):
    n_patches = len(grid)
    if n_patches > batch_size:
        bs = batch_size
        n_batches = int(n_patches / bs + 1)
        for batch_idx in range(n_batches):
            st = batch_idx * bs
            if batch_idx == n_batches - 1:
                if (batch_idx + 1) * bs > n_patches:
                    end = n_patches
                else:
                    end = (batch_idx + 1) * bs
            else:
                end = (batch_idx + 1) * bs
            if st >= end:
                continue
            if batch_idx == 0:
                if img.size(0) != grid.size(0):
                    first_batch_out = F.grid_sample(img.expand(end - st, img.size(1), img.size(2), img.size(3)), grid[st:end, :, :, :])
                else:
                    first_batch_out = F.grid_sample(img[st:end], grid[st:end, :, :, :])
                out_size = torch.Size([n_patches] + list(first_batch_out.size()[1:]))
                out = torch.zeros(out_size, dtype=first_batch_out.dtype)
                out[st:end] = first_batch_out
            elif img.size(0) != grid.size(0):
                out[st:end] = F.grid_sample(img.expand(end - st, img.size(1), img.size(2), img.size(3)), grid[st:end, :, :, :])
