        sq = K.mean(inputs, [1, 2])
    ex = K.dot(sq, kernel1)
    if use_bias:
        ex = K.bias_add(ex, bias1)
    ex = K.relu(ex)
    ex = K.dot(ex, kernel2)
    if use_bias:
        ex = K.bias_add(ex, bias2)
    ex = K.sigmoid(ex)
    if data_format == 'channels_first':
        ex = K.expand_dims(ex, -1)
        ex = K.expand_dims(ex, -1)
    else:
        ex = K.expand_dims(ex, 1)
        ex = K.expand_dims(ex, 1)
    return inputs * ex

import tensorflow as tf
# main code
def softmax(x, axis=1):
    K = tf.keras.backend
    x = K.constant(x)
    ndim = K.ndim(x)

    if ndim == 2:
        return K.softmax(x)
    elif ndim > 2:
        e = K.exp(x - K.max(x, axis=axis, keepdims=True))
        s = K.sum(e, axis=axis, keepdims=True)
        return e / s
    return K.constant([])

import numpy as np

# main code
def clr(base_lr, step_size, scale_fn, clr_iterations, max_lr, scale_mode):
    cycle = np.floor(1 + clr_iterations / (2 * step_size))
    x = np.abs(clr_iterations / step_size - 2 * cycle + 1)
    if scale_mode == 'cycle':
        return base_lr + (max_lr - base_lr) * np.maximum(0, 1 - x) * scale_fn(cycle)
    else:
        return base_lr + (max_lr - base_lr) * np.maximum(0, 1 - x) * scale_fn(clr_iterations)

