    lgb_train = lgb.Dataset(X, y, categorical_feature=cat_cols_to_store)
    gbm = lgb.train(params, lgb_train, num_boost_round=10)

    results['pred'] = gbm.predict(X_test)
    results['categorical_values'] = cat_values

    return results

