def analyze_problem_type(y_train):
    if isinstance(y_train, np.ndarray):
        y_train = pd.Series(y_train)

    unique_values = y_train.nunique()
    if unique_values <= 2:
        return 'Binary_Classification'
    elif unique_values > 10 and np.issubdtype(y_train.dtype, np.number):
        return 'Regression'
    else:
