def stock_prediction(df, model_type='linear'):
    if model_type == 'linear':
        X, Y = df[['Open']].values, df['Adj Close'].values
        model = lgb.LGBMRegressor().fit(X, Y)
        return model.score(X, Y)

    elif model_type == 'logistic':
        X = df.drop('Adj Close', axis=1)
        y = (df['Adj Close'].shift(-1) > df['Adj Close']).astype(int)
        X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.3)
        model = lgb.LGBMClassifier().fit(X_train, y_train)
        return metrics.classification_report(y_test, model.predict(X_test))

    elif model_type == 'svr':
        X, Y = np.arange(len(df)).reshape(-1, 1), df['Adj Close']
        model = lgb.LGBMRegressor().fit(X, Y)
        return model.score(X, Y)

    else:
        return None

import lightgbm as lgb
import pandas as pd

def preprocess_data(data, sample_frac=0.3):
    data_sampled = data.sample(frac=sample_frac, random_state=42)
    X_train = data_sampled.iloc[:, 7:]
    Y_train = data_sampled['CLASS']
    return X_train, Y_train

def tune_hyperparameters(lgb_train):
    best_params = {}
    max_auc = 0.0
    param_grid = {
        'num_leaves': range(5, 100, 5),
        'max_depth': range(3, 8),
        'max_bin': range(5, 256, 10),
    }

    for param, values in param_grid.items():
        for value in values:
            params = {param: value}
            cv_results = lgb.cv(params, lgb_train, seed=1, nfold=5, metrics=['auc'], callbacks=[lgb.early_stopping(5)])
            mean_auc = pd.Series(cv_results['valid auc-mean']).max()
            if mean_auc >= max_auc:
                max_auc = mean_auc
                best_params[param] = value

    return best_params

# main code
def train_model(data):
    X_train, Y_train = preprocess_data(data)
    lgb_train = lgb.Dataset(X_train, Y_train, free_raw_data=False)
    best_params = tune_hyperparameters(lgb_train)

    params = {
        'boosting_type': 'gbdt',
        'objective': 'binary',
        'metric': 'auc'
    }
    params.update(best_params)

    gbm = lgb.train(params, lgb_train, num_boost_round=100, valid_sets=[lgb_train], callbacks=[lgb.early_stopping(5)])
    return gbm, best_params
